request.command:
$ErrorActionPreference = 'Stop'
$managerPackage = Get-Content -LiteralPath 'H:\MTechLabs\MCP\runtime\package.json' -Raw | ConvertFrom-Json
$upstreamPackage = Get-Content -LiteralPath 'H:\MTechLabs\MCP\node_modules\@wonderwhy-er\desktop-commander\package.json' -Raw | ConvertFrom-Json
$sdkPackage = Get-Content -LiteralPath 'H:\MTechLabs\MCP\node_modules\@modelcontextprotocol\sdk\package.json' -Raw | ConvertFrom-Json
$installationRecord = Get-Content -LiteralPath 'H:\MTechLabs\MCP\state\deployment.json' -Raw | ConvertFrom-Json
$listenerCount = @(Get-NetTCPConnection -LocalAddress '127.0.0.1' -LocalPort 19740 -State Listen -ErrorAction Stop).Count
[ordered]@{
  observedAt = [DateTime]::UtcNow.ToString('o')
  manager = [ordered]@{ name = $managerPackage.name; version = $managerPackage.version }
  upstream = [ordered]@{ name = $upstreamPackage.name; version = $upstreamPackage.version }
  sdk = [ordered]@{ name = $sdkPackage.name; version = $sdkPackage.version }
  installationRecord = [ordered]@{
    sourceCommit = $installationRecord.sourceCommit
    completedAt = $installationRecord.completedAt
    workerVersion = $installationRecord.cloudflare.version
    evidence = 'installation-record'
  }
  loopbackAdminListener = [ordered]@{ address = '127.0.0.1'; port = 19740; listening = ($listenerCount -gt 0); listenerCount = $listenerCount }
  limits = 'Package metadata and recorded deployment fields only. No credential reads, HTTP admin authentication, configuration changes, source-byte comparison, or model calls.'
} | ConvertTo-Json -Depth 5 -Compress
